import { fileURLToPath } from "node:url";
// LAWOSS (#440): Bun inlines a CommonJS module's `__filename`/`__dirname` as the absolute path on the building machine
// (undici's index.js reads `__filename` for stack traces). A path-free constant keeps the generated file identical on
// every machine and keeps the developer's disk layout out of the repository and the packaged app.
const result = await Bun.build({ entrypoints: [fileURLToPath(new URL("../src/agent-sandbox/raw-http-node-worker.ts", import.meta.url))], target: "node", format: "cjs", minify: true,
  define: { __filename: JSON.stringify("raw-http-node-worker.js"), __dirname: JSON.stringify(".") } });
if (!result.success || result.outputs.length !== 1) throw new Error(result.logs.join("\n") || "Expected one standalone HTTP worker bundle.");
const undici = import.meta.resolve("undici-transport/package.json"), zod = import.meta.resolve("zod/package.json");
const licenses = await Promise.all([new URL("LICENSE", undici), new URL("lib/web/fetch/LICENSE", undici), new URL("LICENSE", zod)].map(path => Bun.file(path).text()));
const code = `/*! Bundled Undici and Zod licenses:\n${licenses.join("\n")}\n*/\n${await result.outputs[0].text()}`;
const repository = fileURLToPath(new URL("../../../", import.meta.url));
if (code.includes(repository) || code.includes(JSON.stringify(repository).slice(1, -1))) throw new Error("The HTTP worker bundle contains an absolute path of this machine.");
await Bun.write(new URL("../src/agent-sandbox/raw-http-node-code.ts", import.meta.url), `// Generated by scripts/gen-raw-http-node-code.ts; do not edit.\nexport const RAW_HTTP_NODE_CODE = ${JSON.stringify(code)};\n`);
